class TreeNode(var `val`: Int) {
    var left: TreeNode? = null
    var right: TreeNode? = null
}

fun preorder(node: TreeNode?, out: MutableList<Int>) {
    if (node == null) return
    out.add(node.`val`)                 // visit
    preorder(node.left, out)
    preorder(node.right, out)
}

fun inorder(node: TreeNode?, out: MutableList<Int>) {
    if (node == null) return
    inorder(node.left, out)
    out.add(node.`val`)                 // visit
    inorder(node.right, out)
}

fun postorder(node: TreeNode?, out: MutableList<Int>) {
    if (node == null) return
    postorder(node.left, out)
    postorder(node.right, out)
    out.add(node.`val`)                 // visit
}
// Time: O(n)   Space: O(h) call stack

fun preorderIterative(root: TreeNode?): List<Int> {
    val result = mutableListOf<Int>()
    if (root == null) return result
    val stack = ArrayDeque<TreeNode>()
    stack.addLast(root)
    while (stack.isNotEmpty()) {
        val node = stack.removeLast()
        result.add(node.`val`)
        node.right?.let { stack.addLast(it) }     // push right first
        node.left?.let { stack.addLast(it) }      // so left is processed first
    }
    return result
}
// Time: O(n)   Space: O(h)

fun inorderIterative(root: TreeNode?): List<Int> {
    val result = mutableListOf<Int>()
    val stack = ArrayDeque<TreeNode>()
    var curr = root
    while (curr != null || stack.isNotEmpty()) {
        while (curr != null) {                    // go as far left as possible
            stack.addLast(curr)
            curr = curr.left
        }
        val node = stack.removeLast()
        result.add(node.`val`)                    // visit
        curr = node.right                         // then explore the right subtree
    }
    return result
}
// Time: O(n)   Space: O(h)

fun postorderIterative(root: TreeNode?): List<Int> {
    val result = ArrayDeque<Int>()
    if (root == null) return result
    val stack = ArrayDeque<TreeNode>()
    stack.addLast(root)
    while (stack.isNotEmpty()) {
        val node = stack.removeLast()
        result.addFirst(node.`val`)               // root, right, left, then reversed
        node.left?.let { stack.addLast(it) }
        node.right?.let { stack.addLast(it) }
    }
    return result
}
// Time: O(n)   Space: O(h) for the stack, O(n) for the result

fun maxDepth(root: TreeNode?): Int {
    if (root == null) return 0
    return 1 + maxOf(maxDepth(root.left), maxDepth(root.right))
}
// Time: O(n)   Space: O(h)

fun invertTree(root: TreeNode?): TreeNode? {
    if (root == null) return null
    val left = invertTree(root.left)
    val right = invertTree(root.right)
    root.left = right
    root.right = left
    return root
}
// Time: O(n)   Space: O(h)

fun hasPathSum(root: TreeNode?, target: Int): Boolean {
    if (root == null) return false
    if (root.left == null && root.right == null) return root.`val` == target   // leaf
    val remaining = target - root.`val`
    return hasPathSum(root.left, remaining) || hasPathSum(root.right, remaining)
}
// Time: O(n)   Space: O(h)

fun pathSum(root: TreeNode?, targetSum: Int): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun dfs(node: TreeNode?, remaining: Int) {
        if (node == null) return
        path.add(node.`val`)                                   // choose
        if (node.left == null && node.right == null && node.`val` == remaining) {
            result.add(ArrayList(path))                        // copy the current path
        } else {
            dfs(node.left, remaining - node.`val`)
            dfs(node.right, remaining - node.`val`)
        }
        path.removeAt(path.lastIndex)                          // un-choose (backtrack)
    }

    dfs(root, targetSum)
    return result
}
// Time: O(n * h) in the worst case because of path copies   Space: O(h)

fun sumNumbers(root: TreeNode?): Int {
    fun dfs(node: TreeNode?, current: Int): Int {
        if (node == null) return 0
        val value = current * 10 + node.`val`
        if (node.left == null && node.right == null) return value
        return dfs(node.left, value) + dfs(node.right, value)
    }
    return dfs(root, 0)
}
// Time: O(n)   Space: O(h)

fun binaryTreePaths(root: TreeNode?): List<String> {
    val result = mutableListOf<String>()

    fun dfs(node: TreeNode?, path: String) {
        if (node == null) return
        val current = if (path.isEmpty()) "${node.`val`}" else "$path->${node.`val`}"
        if (node.left == null && node.right == null) {
            result.add(current)
            return
        }
        dfs(node.left, current)
        dfs(node.right, current)
    }

    dfs(root, "")
    return result
}
// Time: O(n * h) for building strings   Space: O(h)

fun pathSumIII(root: TreeNode?, targetSum: Int): Int {
    val prefixCount = HashMap<Long, Int>()
    prefixCount[0L] = 1

    fun dfs(node: TreeNode?, current: Long): Int {
        if (node == null) return 0
        val sum = current + node.`val`
        var count = prefixCount[sum - targetSum] ?: 0          // paths ending here
        prefixCount[sum] = (prefixCount[sum] ?: 0) + 1
        count += dfs(node.left, sum) + dfs(node.right, sum)
        prefixCount[sum] = prefixCount[sum]!! - 1              // backtrack
        return count
    }

    return dfs(root, 0L)
}
// Time: O(n)   Space: O(h)
// Same idea as Subarray Sum Equals K, applied to root-to-node paths

fun diameterOfBinaryTree(root: TreeNode?): Int {
    var best = 0

    fun height(node: TreeNode?): Int {
        if (node == null) return 0
        val l = height(node.left)
        val r = height(node.right)
        best = maxOf(best, l + r)               // longest path through this node
        return 1 + maxOf(l, r)                  // but only one side can extend upward
    }

    height(root)
    return best
}
// Time: O(n)   Space: O(h)

fun maxPathSum(root: TreeNode?): Int {
    var best = Int.MIN_VALUE

    fun gain(node: TreeNode?): Int {
        if (node == null) return 0
        val l = maxOf(0, gain(node.left))       // ignore negative branches
        val r = maxOf(0, gain(node.right))
        best = maxOf(best, node.`val` + l + r)  // path that bends at this node
        return node.`val` + maxOf(l, r)         // path that continues upward
    }

    gain(root)
    return best
}
// Time: O(n)   Space: O(h)

fun lowestCommonAncestor(root: TreeNode?, p: TreeNode, q: TreeNode): TreeNode? {
    if (root == null || root === p || root === q) return root
    val left = lowestCommonAncestor(root.left, p, q)
    val right = lowestCommonAncestor(root.right, p, q)
    return if (left != null && right != null) root     // p and q are on different sides
    else left ?: right                                  // both are on one side
}
// Time: O(n)   Space: O(h)

import kotlin.math.abs

fun isBalanced(root: TreeNode?): Boolean {
    fun height(node: TreeNode?): Int {
        if (node == null) return 0
        val l = height(node.left)
        if (l == -1) return -1                  // left subtree already unbalanced
        val r = height(node.right)
        if (r == -1) return -1
        if (abs(l - r) > 1) return -1
        return 1 + maxOf(l, r)
    }
    return height(root) != -1
}
// Time: O(n)   Space: O(h)
// Calling height() repeatedly from each node would be O(n²)

fun isSubtree(root: TreeNode?, subRoot: TreeNode?): Boolean {
    if (subRoot == null) return true
    if (root == null) return false
    return isSameTree(root, subRoot) ||
        isSubtree(root.left, subRoot) ||
        isSubtree(root.right, subRoot)
}
// Time: O(n * m)   Space: O(h)

fun goodNodes(root: TreeNode?): Int {
    fun dfs(node: TreeNode?, maxSoFar: Int): Int {
        if (node == null) return 0
        val good = if (node.`val` >= maxSoFar) 1 else 0
        val newMax = maxOf(maxSoFar, node.`val`)
        return good + dfs(node.left, newMax) + dfs(node.right, newMax)
    }
    return dfs(root, Int.MIN_VALUE)
}
// Time: O(n)   Space: O(h)

fun buildTree(preorder: IntArray, inorder: IntArray): TreeNode? {
    val indexOf = HashMap<Int, Int>()
    for ((i, v) in inorder.withIndex()) indexOf[v] = i
    var preIdx = 0

    fun build(left: Int, right: Int): TreeNode? {
        if (left > right) return null
        val rootVal = preorder[preIdx++]                  // preorder gives the root first
        val root = TreeNode(rootVal)
        val mid = indexOf[rootVal]!!                      // inorder splits left and right
        root.left = build(left, mid - 1)
        root.right = build(mid + 1, right)
        return root
    }

    return build(0, inorder.size - 1)
}
// Time: O(n)   Space: O(n)
// Build the left subtree before the right one because preIdx moves in preorder

fun flatten(root: TreeNode?) {
    var curr = root
    while (curr != null) {
        val left = curr.left
        if (left != null) {
            var pred: TreeNode = left
            while (pred.right != null) pred = pred.right!!    // rightmost node of the left subtree
            pred.right = curr.right                           // attach the old right subtree
            curr.right = left                                 // move the left subtree to the right
            curr.left = null
        }
        curr = curr.right
    }
}
// Time: O(n)   Space: O(1)
// Result follows preorder order

// A skewed tree with 100,000 nodes can overflow the default call stack.
// Option 1: use an iterative version with your own stack (see the templates above).
// Option 2: run the recursion in a thread with a larger stack:
fun runWithBigStack(block: () -> Unit) {
    val t = Thread(null, block, "dfs", 512L * 1024 * 1024)
    t.start()
    t.join()
}
